import java.util.*;

class Solution {
  private final int rows, cols;
  private int remaining;
  private final Map<Integer, Integer> swaps = new HashMap<>();
  private final Random random = new Random();

  public Solution(int m, int n) {
    rows = m;
    cols = n;
    remaining = m * n;
  }

  public int[] flip() {
    int index = random.nextInt(remaining--);
    int chosen = swaps.getOrDefault(index, index);
    swaps.put(index, swaps.getOrDefault(remaining, remaining));
    return new int[] {chosen / cols, chosen % cols};
  }

  public void reset() {
    swaps.clear();
    remaining = rows * cols;
  }
}
